<?php $page_title='Dashboard'; require_once __DIR__.'/includes/header.php';
$stats=['total'=>one('SELECT COUNT(*) c FROM trial_requests')['c']??0,'pending'=>one("SELECT COUNT(*) c FROM trial_requests WHERE status='pending'")['c']??0,'approved'=>one("SELECT COUNT(*) c FROM trial_requests WHERE status='approved'")['c']??0,'rejected'=>one("SELECT COUNT(*) c FROM trial_requests WHERE status='rejected'")['c']??0,'today'=>one('SELECT COUNT(*) c FROM trial_requests WHERE DATE(created_at)=CURDATE()')['c']??0];
$recent=all('SELECT * FROM trial_requests ORDER BY id DESC LIMIT 8');
?><div class="row"><?php foreach($stats as $k=>$v): ?><div class="col-lg-3 col-md-4"><div class="card stat"><div class="card-body"><small class="text-muted"><?=e(ucfirst($k))?> Requests</small><h3><?=number_format($v)?></h3></div></div></div><?php endforeach; ?></div><div class="card mt-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h4>Recent Requests</h4><a class="btn btn-primary" href="request-edit.php">New Request</a></div><div class="table-wrap"><table class="table"><tr><th>Name</th><th>WhatsApp</th><th>Country</th><th>Plan</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $r): ?><tr><td><a href="request-view.php?id=<?=$r['id']?>"><?=e($r['name'])?></a><br><small class="text-muted"><?=e($r['email'])?></small></td><td><?=e($r['whatsapp'])?></td><td><?=e($r['country'])?></td><td><?=e($r['plan'])?></td><td><?=status_badge($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach; ?></table></div></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
